What will be printed when the following Java code executes?<br><br><div class='code-block'>public class Main {
    public static void main(String[] args) {
        String s1 = "Java";
        String s2 = new String("Java");
        System.out.print((s1 == s2) + " " + s1.equals(s2));
    }
}</div>

Examine the following C++ code. What is its output?<br><br><div class='code-block'>#include &lt;iostream&gt;
using namespace std;
void solve(int &x, int y) {
    x = x + 10;
    y = y + 10;
}
int main() {
    int a = 5, b = 5;
    solve(a, b);
    cout << a << " " << b;
    return 0;
}</div>

